import { createHmac, timingSafeEqual } from 'node:crypto';

// secret: your signing secret, shown once at creation (format "whsec_<base64>").
// rawBody: the EXACT bytes of the request body — do NOT re-serialize parsed JSON.
export function verifyWebhook(headers, rawBody, secret) {
  const id = headers['webhook-id'];
  const timestamp = headers['webhook-timestamp'];
  const sigHeader = headers['webhook-signature']; // space-delimited list of "v1,<base64>"

  // Reject anything missing or malformed (treat any error as a rejection).
  if (!id || !timestamp || !sigHeader || !/^\d+$/.test(timestamp)) {
    throw new Error('invalid webhook request');
  }
  // Replay protection: reject deliveries older than 5 minutes.
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) {
    throw new Error('stale webhook');
  }

  // HMAC key = base64-decode of the secret AFTER the "whsec_" prefix.
  const key = Buffer.from(secret.replace(/^whsec_/, ''), 'base64');
  const signedContent = `${id}.${timestamp}.${rawBody}`;
  const expected = createHmac('sha256', key).update(signedContent, 'utf8').digest('base64');

  // Accept if ANY of the space-delimited signatures matches (supports key rotation).
  const ok = sigHeader.split(' ').some((token) => {
    const sig = token.startsWith('v1,') ? token.slice(3) : token;
    const a = Buffer.from(sig);
    const b = Buffer.from(expected);
    return a.length === b.length && timingSafeEqual(a, b);
  });
  if (!ok) throw new Error('invalid signature');
  // OK — dedupe on `id` before processing (retries reuse it).
}

